import java.util.concurrent.*

class AvoidCompletionServiceTakeTest<T> {
    private val complServField: CompletionService<List<T>>? = null

    fun collectAllBad(completionService: CompletionService<List<T>>, responseCollector: MutableList<Any>) {
        val futureLocal = completionService.take()  // bad
        val runFut = CompletableFuture.supplyAsync { emptyList<Any>() }
        responseCollector.addAll(runFut.get(3L, TimeUnit.SECONDS)) // good
        take() // good, different take() method
    }

    fun collectAllBad2(execComplSrv: ExecutorCompletionService<Any>) {
        val future = complServField!!.take() // bad
        val take2 = execComplSrv.take() // bad
    }

    fun take(): Any? = null
}
